      renwu = "npc",
      role1 = 386000,
      role2 = 302101,
      role3 = 302205,
      role6 = 3855002,
      sentence = "We all have to grow up. Each birthday you have to tell yourself: You've grown up now. You have to learn to understand and accept things.",
